// Loads the WebAuthn fixtures (generated by scripts/generate-contract-fixtures.mjs,
// kept in sync with the auth provider) for the contract tests.
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), 'fixtures');

export interface ContractParams {
  rpId: string;
  origin: string;
  challenge: string;
  userId: string;
  credentialId: string;
  cosePublicKey: string;
}

export const params = JSON.parse(
  readFileSync(path.join(dir, 'params.json'), 'utf8'),
) as ContractParams;

export const attestation = JSON.parse(
  readFileSync(path.join(dir, 'attestation.json'), 'utf8'),
);

export const assertion = JSON.parse(
  readFileSync(path.join(dir, 'assertion.json'), 'utf8'),
);
